const subjects=[
    {"name":"保育の心理学","enname":"shinri","color":"rgba(255,105,180,1)","theme_list":[
        {"theme": "条件づけ", "quantity": 11, "theme_comment": "条件づけの理論は、今でも教育や保育の分野で応用されて、現場での実践にも役立てられています。\n\n基礎的な部分の理解は応用にも活きますので、ぜひ実際の保育で応用するところまで想像しながら学んでいきましょう。", "questions": [{"tag": 0, "q_type": null, "pre_question": "", "question_id": "shinri_01_001", "block_shuffle": null, "question": "例えばレモンを見て唾液が出るなど、もともと反応を引き起こさなかった刺激が、学習の結果、刺激と反応が結びついてしまい、ある反応を引き起こすようになることを何と言うか？", "question_img": null, "choices": ["古典的条件づけ", "道具的条件づけ"], "answer": 0, "comment_1": "難しい文章でしたが、よく「条件反射」として語られる現象です。\n\nレモンの例でも、\n何も知らない人は、レモンを見ても唾液が出てきたりしませんが、\n経験によって「レモン=酸っぱい」みたいなイメージがつきます。\nその結果、「レモン→唾液」という流れが出来上がってしまうのです。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "shinri_01_002", "block_shuffle": null, "question": "古典的条件づけの別名は？", "question_img": null, "choices": ["レスポンデント条件づけ", "オペラント条件付け"], "answer": 0, "comment_1": "レモンへのレスポンスとして反射が起こる、みたいな感じですね。\n\n試験では、基本的にどちらか片方しか名前が出てこないので、\n「古典的条件づけ」と「レスポンデント条件づけ」の両方を覚えておきましょう。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "shinri_01_003", "block_shuffle": null, "question": "犬にベルの音を聞かせた後に餌を与える実験で、古典的条件づけを明らかにした人物は誰か。", "question_img": null, "choices": ["パブロフ", "ワトソン", "スキナー", "アルバート"], "answer": 0, "comment_1": "「パブロフの犬」と呼ばれる、とても有名な実験です。\n\nこれも「ベルの音=餌」という学習をしており、\n「ベルの音→唾液」という流れができています。\nまさに刺激と反応が結びついていますね。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "shinri_01_004", "block_shuffle": null, "question": "ネズミを使った実験で、レバーを引けば餌が出てくる、ということに気づいたネズミが、自分から何回もレバーを引くようになったことを報告した人物と言えば？", "question_img": null, "choices": ["パブロフ", "ワトソン", "スキナー", "アルバート"], "answer": 2, "comment_1": "ネズミを使った実験と言えば、かなり残酷なものが多いイメージですが、わりと平和な感じの実験ですね。\nネズミが好きなスキナー、という感じで覚えましょう。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "shinri_01_005", "block_shuffle": null, "question": "スキナーがネズミの実験をもとに提唱した理論で、ある行動をすると、良いこと(悪いこと)が起こることを学習した結果、その行動が増える(減る)ことを説明するメカニズムと言えば？", "question_img": null, "choices": ["古典的条件づけ", "道具的条件づけ", "観察学習", "SOC理論"], "answer": 1, "comment_1": "オペラント条件づけでは、行動が増えることも減ることもあります。\n\n【良いことがあると学習した場合】\nお手伝いをして褒められた結果、\n何度もお手伝いをするようになった。\n\n【悪いことがあると学習した場合】\nお手伝いをしたが、出来ていない点ばかり指摘されて嫌な気持ちになり、\nあまりお手伝いをしなくなった。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "shinri_01_006", "block_shuffle": null, "question": "道具的条件づけの別名は？", "question_img": null, "choices": ["レスポンデント条件づけ", "オペラント条件付け"], "answer": 1, "comment_1": "オペラント条件づけと道具的条件づけ、これまた両方とも覚える必要があります。少し大変ですが、どちらが出ても分かるようにしておきましょうね。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "shinri_01_007", "block_shuffle": null, "question": "オペラント条件づけの理論を応用してスキナーが提案した学習法で、スモールステップや即時フィードバック、学習者のペースで行うなどの特徴を持つものと言えば何？", "question_img": null, "choices": ["観察学習", "プログラム学習", "発見学習", "洞察学習"], "answer": 1, "comment_1": "教育原理でも出てくるキーワードです。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "shinri_01_008", "block_shuffle": null, "question": "子どもが白いネズミに近づこうとするたびに大きな音を鳴らして驚かせることを繰り返した結果、子どもが白いネズミを怖がるようになった実験を行った人物は？", "question_img": null, "choices": ["パブロフ", "ワトソン", "スキナー", "アルバート"], "answer": 1, "comment_1": "研究を行った人物の名前は「ワトソン」ですが、\n\nこの実験は、被験者の子供の名前を取って、「アルバート坊やの実験」と呼ばれます。\n\n現在は倫理的に問題がある実験です。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "shinri_01_009", "block_shuffle": null, "question": "アルバート坊やの実験は、どっち？", "question_img": null, "choices": ["レスポンデント条件づけ", "オペラント条件付け"], "answer": 0, "comment_1": "「ネズミ=大きな音」と結びついてしまい、「ネズミ→恐怖反応」という流れができています。\n刺激と反応が結びついているので、レスポンデント条件づけになります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "これはどっちの事例？", "question_id": "shinri_01_010", "block_shuffle": null, "question": "お手伝いをして褒められた子どもが、何度もお手伝いをするようになった。", "question_img": null, "choices": ["レスポンデント条件づけ", "オペラント条件付け"], "answer": 1, "comment_1": "お手伝いをしたら良いことがある(褒められる)と学習した結果、\n行動の「頻度」が変化していますので、オペラント条件づけです。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "これはどっちの事例？", "question_id": "shinri_01_011", "block_shuffle": null, "question": "病院で白衣を着た医師に注射をされて怖い思いをした子どもが、白衣を見ただけで泣き出すようになった。", "question_img": null, "choices": ["レスポンデント条件づけ", "オペラント条件付け"], "answer": 0, "comment_1": "「白衣=注射(痛かった)」と結びついてしまい、「白衣→恐怖反応(泣き出す)」という流れができています。\n刺激と反応が結びついているので、レスポンデント条件づけになります。", "goro_img": null, "comment_2": null, "mitei": null}]},
        {"theme": "発達を決めるもの", "quantity": 9, "theme_comment": "「氏か育ちか」\nという言葉のように、昔から、\n発達は遺伝で決まるのか、それとも環境で決まるのか、といった議論がありました。\n\n現在は「どっちも重要(相互作用がある)」という考え方が主流ですが、\nこのテーマでは、これまでの議論の歴史を学んでいきます。", "questions": [{"tag": 0, "q_type": null, "pre_question": "これは誰？", "question_id": "shinri_02_001", "block_shuffle": null, "question": "一卵性双生児の階段登りの実験の結果から、発達は基本的に神経系の成熟によって規定されるとした人物は誰？", "question_img": null, "choices": ["ゲゼル", "ゴールトン", "ワトソン", "シュテルン"], "answer": 0, "comment_1": "階段のぼりの実験と言えばゲゼルですね。\n赤ちゃんを小さいころから訓練しても、特別に早く階段が登れるようにはならなかったので、適切なタイミングまで成熟するのを待ったほうがいいんじゃないか？みたいな考え方をした人です。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "これは何？", "question_id": "shinri_02_002", "block_shuffle": null, "question": "「発達は基本的に神経系の成熟によって規定される」という考え方を何説というか？", "question_img": null, "choices": ["成熟優位説", "輻輳説", "環境閾値説"], "answer": 0, "comment_1": "ゲゼルの唱えていた説ですね。\n年齢が上がって神経系が成熟していくとともに、いろいろなことを学べる状態が整っていく、という考え方です。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "これは何？", "question_id": "shinri_02_003", "block_shuffle": null, "question": "学習の成立にとって必要な、個体の発達的素地、心身の準備性のことを何というか？", "question_img": null, "choices": ["レディネス", "臨界期", "敏感期", "神経可塑性"], "answer": 0, "comment_1": "「レディーゴー!」のレディーなので準備、みたいな感じで覚えましょう。\n\n階段のぼりを習得するには、階段のぼりを習得できる程度に成熟していること、つまり階段を上るためのレディネスが必要、ということです。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "これは誰？", "question_id": "shinri_02_004", "block_shuffle": null, "question": "遺伝説の立場から、「優秀な遺伝子を持った人同士で子孫を残せば優秀な人が生まれるはずだ」と考えた人物と言えば？", "question_img": null, "choices": ["ゲゼル", "ゴールトン", "ワトソン", "シュテルン"], "answer": 1, "comment_1": "このような考え方を優生思想、と言います。\n(昔流行ったけっこうヤバい思想です)\n\n【優生思想】\n優秀な遺伝子を持つ人の子孫は優秀\n劣った遺伝子を持つ人の子孫は劣等\n\nこのあたりは色々と闇が深いですが、こんな歴史があるということは知っておきましょう。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "これは誰？", "question_id": "shinri_02_005", "block_shuffle": null, "question": "アルバート坊やの恐怖条件づけの実験で知られるワトソンは、どの立場を取っていた？", "question_img": null, "choices": ["遺伝説", "環境説", "相互作用説"], "answer": 1, "comment_1": "ワトソンは、アルバート坊やの実験で条件づけを行った人物です。\n\n子どもが条件づけによって変わった\nという実験結果などから、\n「発達は条件づけによって説明できる」と考え、\n環境説の立場をとっていました。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "これは何？", "question_id": "shinri_02_006", "block_shuffle": null, "question": "発達は、遺伝と環境の単純な加算(足し算)によって決まるものである、とする理論は何か。", "question_img": null, "choices": ["相互作用説", "輻輳説", "環境閾値説"], "answer": 1, "comment_1": "輻輳(ふくそう)説では、遺伝と環境がどちらも大事だと考えていますが、\n遺伝と環境の「相互作用」についてまでは考慮していません。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "輻輳説でもう一問。", "question_id": "shinri_02_007", "block_shuffle": null, "question": "輻輳説を唱えた人物は誰？", "question_img": null, "choices": ["ゲゼル", "ゴールトン", "ジェンセン", "シュテルン"], "answer": 3, "comment_1": null, "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "ちょっと難問。これは何？", "question_id": "shinri_02_008", "block_shuffle": null, "question": "個々の特性が表れるのに必要な環境的要因には、特性ごとに固有な最低限度(閾値）がある、という考え方と言えば何？", "question_img": null, "choices": ["相互作用説", "輻輳説", "環境閾値説", "成熟優位説"], "answer": 2, "comment_1": "遺伝的要素が出てくるためには、最低限の環境(閾値 いきち)が必要ですよ、という考え方です。\n\n例えばいくら高身長の遺伝子を持っていても、栄養をまともに与えられなかったら背は伸びにくいですよね。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "これは誰？", "question_id": "shinri_02_009", "block_shuffle": null, "question": "環境閾値説を提唱した人物は誰？", "question_img": null, "choices": ["ワトソン", "フロイト", "ジェンセン", "シュテルン"], "answer": 2, "comment_1": "シュテルン→輻輳説\nジェンセン→環境閾値説\n\n名前が似ているので注意しましょう。", "goro_img": null, "comment_2": null, "mitei": null}]}
    ]},
    {"name":"保育原理","enname":"hogen","color":"rgba(220,20,60,1)","theme_list":[
        {"theme": "保育士資格", "quantity": 9, "theme_comment": "保育士を目指すなら必ず知っておきたい、保育士資格に関する問題です。\n保育士の業務内容や義務などについて学びましょう。", "questions": [{"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_01_001", "block_shuffle": null, "question": "保育士資格は、どんな国家資格？", "question_img": null, "choices": ["名称独占", "業務独占"], "answer": 0, "comment_1": "名称独占なので、保育士じゃない人が「保育士」を名乗ったらダメ、ということです。\n\n【児童福祉法】\n保育士でない者は、保育士又はこれに紛らわしい名称を使用してはならない。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_01_002", "block_shuffle": null, "question": "「保育士」について規定している法律の名前は？", "question_img": null, "choices": ["こども基本法", "子ども・子育て支援法", "児童福祉法", "教育基本法"], "answer": 2, "comment_1": "【児童福祉法の規定】\n保育士とは、 登録を受け、保育士の名称を用いて、専門的知識及び技術をもつて、児童の保育及び児童の保護者に対する保育に関する指導を行うことを業とする者をいう。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": "正誤", "pre_question": "", "question_id": "hogen_01_003", "block_shuffle": null, "question": "保育士となる資格を有する者が保育士となるには、保育士登録を受けなければならない。", "question_img": null, "choices": ["○", "×"], "answer": 0, "comment_1": "保育士は、登録が必要な資格です。\n\n【児童福祉法】\n保育士となる資格を有する者が保育士となるには、保育士登録簿に、氏名、生年月日その他内閣府令で定める事項の登録を受けなければならない。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_01_004", "block_shuffle": null, "question": "申請者に対し、「保育士登録証」を交付することになっているのは？", "question_img": null, "choices": ["市町村長", "都道府県知事"], "answer": 1, "comment_1": "実は頻出の問題です。\nちなみに、保育士登録簿も、「都道府県」に置かれます。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": "正誤", "pre_question": "○か×か。", "question_id": "hogen_01_005", "block_shuffle": null, "question": "保育士は、正当な理由なく、業務に関して知り得た人の秘密を漏らしてはならないが、保育士でなくなった後はこの限りではない。", "question_img": null, "choices": ["○", "×"], "answer": 1, "comment_1": "保育士をやめてからも、守秘義務が課されます。\n\n【児童福祉法】\n保育士は、正当な理由がなく、その業務に関して知り得た人の秘密を漏らしてはならない。保育士でなくなつた後においても、同様とする。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": "正誤", "pre_question": "○か×か。", "question_id": "hogen_01_006", "block_shuffle": null, "question": "保育士は、保育士の信用を傷つけてはならない。", "question_img": null, "choices": ["○", "×"], "answer": 0, "comment_1": "これは児童福祉法の文章です。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": "正誤", "pre_question": "○か×か。", "question_id": "hogen_01_007", "block_shuffle": null, "question": "保育士は、資格更新のため定期的に所定の講習を受講しなければならない。", "question_img": null, "choices": ["○", "×"], "answer": 1, "comment_1": "保育士資格は、更新不要で、1回資格を取れば基本的に生涯有効な資格です。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "穴埋め問題。", "question_id": "hogen_01_008", "block_shuffle": null, "question": "保育士とは、 登録を受け、保育士の名称を用いて、専門的知識及び技術をもつて、児童の保育及び児童の保護者に対する保育に関する○○を行うことを業とする者をいう。", "question_img": null, "choices": ["指導", "支援", "教育"], "answer": 0, "comment_1": "児童福祉法の文章です。頻出ですのでしっかり覚えましょう。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_01_009", "block_shuffle": 1, "question": "児童福祉法が改正・施行され、保育士が国家資格となったのは何年？", "question_img": null, "choices": ["1983年", "1993年", "2003年", "2013年"], "answer": 2, "comment_1": "2003年と言えば「ゲッツ」が流行った時期です。(懐かしいですね)\n\n保育士資格を「ゲッツ！」ということですね。", "goro_img": null, "comment_2": null, "mitei": null}]},
        {"theme": "児童と妊産婦の定義", "quantity": 9, "theme_comment": "新生児、乳児、幼児、少年、妊産婦とは具体的にどんな人を指すのか、詳しく学びます。\n年齢などの定義だけでなく、どの法律に書いてあるかまで、しっかり覚えましょう。", "questions": [{"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_02_001", "block_shuffle": 1, "question": "児童福祉法による「児童」の定義は？", "question_img": null, "choices": ["満十五歳に満たない者", "満十八歳に満たない者", "満二十歳に満たない者", "心身の発達の過程にある者"], "answer": 1, "comment_1": null, "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_02_002", "block_shuffle": 1, "question": "児童福祉法による「乳児」の定義は？", "question_img": null, "choices": ["満一歳に満たない者", "満二歳に満たない者", "満三歳に満たない者"], "answer": 0, "comment_1": "乳児の定義：\n満一歳に満たない者\n\n母子保健法でも同じ定義があります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_02_003", "block_shuffle": null, "question": "児童福祉法による「幼児」の定義は、満一歳からいつまでの者？", "question_img": null, "choices": ["小学校就学の始期に達するまでの者", "満六歳に満たない者"], "answer": 0, "comment_1": "幼児の定義：\n満一歳から、小学校就学の始期に達するまでの者\n\n母子保健法でも同じ定義があります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_02_004", "block_shuffle": 1, "question": "児童福祉法による「少年」の定義は、小学校就学の始期からいつまでの者？", "question_img": null, "choices": ["満十五歳に満たない者", "満十八歳に満たない者", "満二十歳に満たない者"], "answer": 1, "comment_1": "少年の定義：\n小学校就学の始期から、満十八歳に達するまでの者", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_02_005", "block_shuffle": 1, "question": "児童福祉法による「妊産婦」の定義は？", "question_img": null, "choices": ["妊娠中又は出産後半年以内の女子", "妊娠中又は出産後一年以内の女子", "妊娠中又は出産後二年以内の女子"], "answer": 1, "comment_1": "【児童福祉法】\nこの法律で、妊産婦とは、妊娠中又は出産後一年以内の女子をいう。\n\n母子保健法でも同じ定義があります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_02_006", "block_shuffle": 1, "question": "児童の権利に関する条約によると、児童は原則何歳未満？", "question_img": null, "choices": ["15歳未満", "18歳未満", "20歳未満", "22歳未満"], "answer": 1, "comment_1": "【児童の権利に関する条約】\nこの条約の適用上、児童とは、18歳未満のすべての者をいう。\nただし、当該児童で、その者に適用される法律によりより早く成年に達したものを除く。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_02_007", "block_shuffle": 1, "question": "「新生児」とは、生後何日未満の子どもを指すか？", "question_img": null, "choices": ["7日未満", "14日未満", "28日未満", "60日未満"], "answer": 2, "comment_1": "28日は、ちょうど4週間ですね。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_02_008", "block_shuffle": null, "question": "新生児について定義している法律と言えば？", "question_img": null, "choices": ["児童福祉法", "母子保健法", "こども基本法", "子ども・子育て支援法"], "answer": 1, "comment_1": "児童の定義と言えば児童福祉法などが浮かびますが、\n新生児の定義があるのは「母子保健法」です。\n引っかけに気をつけましょう。\n\n【母子保健法】\nこの法律において「新生児」とは、出生後二十八日を経過しない乳児をいう。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_02_009", "block_shuffle": 1, "question": "こども基本法において、「こども」とは？", "question_img": null, "choices": ["18歳未満の者", "20歳未満の者", "22歳未満の者", "心身の発達の過程にある者"], "answer": 3, "comment_1": "【こども基本法】\nこの法律において「こども」とは、心身の発達の過程にある者をいう。\n\nこども基本法は、2023年に施行された、比較的新しい法律です。\n「こども」の考え方も新しい感じがしますね。", "goro_img": null, "comment_2": null, "mitei": null}]},
        {"theme": "保育所の職員", "quantity": 10, "theme_comment": "保育士の活躍の場は保育所(保育園)だけとは限りませんが、やはり試験ではよく問われる内容です。\n\nここでは、子どもたちの「生活の場」としての保育所の「職員配置」について学びましょう。", "questions": [{"tag": 0, "q_type": null, "pre_question": "これは、何の文章？", "question_id": "hogen_03_001", "block_shuffle": null, "question": "保育所には、保育士、嘱託医及び調理員を置かなければならない。ただし、調理業務の全部を委託する施設にあつては、調理員を置かないことができる。", "question_img": null, "choices": ["児童福祉施設の設備及び運営に関する基準", "保育所保育指針", "児童福祉法", "こども基本法"], "answer": 0, "comment_1": "名前が長いですが、児童福祉施設の設備及び運営に関する基準は、ここから何回も出てきます。\n\n児童福祉施設(保育所や児童館など)の職員配置や設備の基準については、だいたいこの基準に書いてあります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_03_002", "block_shuffle": 1, "question": "1つの保育所において、原則として、保育士の数は最低でも何人を下ることができないとされている？", "question_img": null, "choices": ["1人", "2人", "3人", "4人"], "answer": 1, "comment_1": "2人以上の要件は「保育所の規模に関わらず」適用されます。\n\nここで言う「保育士」には、\n\n・地域限定保育士\n・国家戦略特別区域限定保育士\n\nも含まれます。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_03_003", "block_shuffle": null, "question": "保育所の職員配置の特例として、当分の間、保育士とみなされるのは？", "question_img": null, "choices": ["幼稚園教諭", "子育て支援員", "児童福祉司", "臨床心理士"], "answer": 0, "comment_1": "色々と細かいルールはあるようですが、現在の保育の受け皿不足を考慮した経過措置です。\n\n・幼稚園教諭\n・小学校教諭\n・養護教諭\n\nのどれかの普通免許状を持っている人が「保育士」としてみなされます。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_03_004", "block_shuffle": 1, "question": "保育所での保育士の配置基準は、乳児おおむね何人に対して1人以上？", "question_img": null, "choices": ["3人につき1人以上", "5人につき1人以上", "6人につき1人以上", "10人につき1人以上"], "answer": 0, "comment_1": "乳児とは、0歳児のことです。\n\n保育園では2歳クラスまで「乳児さん」と呼ぶこともありますが、\n保育士試験では(そして法的には)「乳児=0歳児」です。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_03_005", "block_shuffle": 1, "question": "保育所での保育士の配置基準は、「満一歳以上満三歳に満たない幼児」おおむね何人に対して1人以上？", "question_img": null, "choices": ["5人につき1人以上", "6人につき1人以上", "10人につき1人以上", "15人につき1人以上"], "answer": 1, "comment_1": "満一歳以上満三歳に満たない幼児ということは、\n\n要するに、\n・1歳クラス\n・2歳クラス\nの子どもたちのことです。\n\n最近は手厚い保育を目指して配置基準も変わってきていますね。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_03_006", "block_shuffle": 1, "question": "保育所での保育士の配置基準は、「満三歳以上満四歳に満たない幼児」おおむね何人に対して1人以上？", "question_img": null, "choices": ["10人につき1人以上", "15人につき1人以上", "25人につき1人以上", "30人につき1人以上"], "answer": 1, "comment_1": "満三歳以上満四歳に満たない幼児ということは、\n\n要するに、\n・3歳クラス\nの子どもたちのことですね。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_03_007", "block_shuffle": 1, "question": "保育所での保育士の配置基準は、「満四歳以上の幼児」おおむね何人に対して1人以上？", "question_img": null, "choices": ["15人につき1人以上", "25人につき1人以上", "30人につき1人以上", "40人につき1人以上"], "answer": 1, "comment_1": "配置基準まとめ\n\n乳児→3人\n満1歳以上満3歳未満→6人\n満3歳以上満4歳未満→15人\n満4歳以上→25人\n\n(保育士1人あたり)", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hogen_03_008", "block_shuffle": 1, "question": "保育所において、特定の要件を満たす場合にのみ例外的に「外部で調理し搬入する方法（外注給食）」も認められる児童と言えば？", "question_img": null, "choices": ["満1歳以上の幼児", "満3歳以上の幼児", "アレルギーのない児童"], "answer": 1, "comment_1": "ピンポイントで年齢を問われる問題が頻出です。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": "正誤", "pre_question": "○か×か。", "question_id": "hogen_03_009", "block_shuffle": null, "question": "当面の間、子育てに関する知識及び経験を有する「理学療法士」は、保育士の算定の時に、保育士による支援体制があり、なおかつ1人まで、という条件付きで、保育士として算定できる。", "question_img": null, "choices": ["○", "×"], "answer": 0, "comment_1": "対象になるのは、\n\n・理学療法士\n・作業療法士\n・言語聴覚士\n・心理担当職員\n・障害児の療育に関する知識及び経験を有する者(経験五年以上)\n\nです。\n\nただし、どの資格があったとしても、\n「子育てに関する知識及び経験を有する者」\nでなければなりません。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "ここで復習。○○に入るのは？", "question_id": "hogen_03_010", "block_shuffle": null, "question": "保育所には、保育士、○○及び調理員を置かなければならない。ただし、調理業務の全部を委託する施設にあつては、調理員を置かないことができる。", "question_img": null, "choices": ["看護師", "嘱託医", "園長", "事務員"], "answer": 1, "comment_1": "嘱託医は、保育所での健診なども担当します。", "goro_img": null, "comment_2": null, "mitei": null}]}
    ]},
    {"name":"子ども家庭福祉","enname":"kofuku","color":"rgba(65,105,225,1)","theme_list":[
        {"theme": "児童手当等", "quantity": 14, "theme_comment": "「児童手当」「児童扶養手当」「特別児童扶養手当」など、特に子育て経験者にとっては馴染み深く、関心も高い分野ですね。\n\n福祉系分野を苦手とする方は多いですが、\n「ここは知ってる」\n「ちょっと興味ある」\nというテーマを足掛かりにすると、\n勉強が進みやすくなります。\n\n少しづつ知識を拡げていきましょう。", "questions": [{"tag": 0, "q_type": null, "pre_question": "", "question_id": "kofuku_01_001", "block_shuffle": 1, "question": "基本的に「全ての児童」の保護者に対して支給される手当と言えば？", "question_img": null, "choices": ["児童手当", "児童扶養手当", "特別児童扶養手当"], "answer": 0, "comment_1": "ちなみに、児童手当の支給について定めている法律は、児童手当法です。\n（そのままですね。）", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kofuku_01_002", "block_shuffle": 1, "question": "主に「ひとり親家庭の保護者」を対象とした手当と言えばどっち？", "question_img": null, "choices": ["児童扶養手当", "特別児童扶養手当"], "answer": 0, "comment_1": "超ざっくりまとめ↓\n\n児童手当→全員\n児童扶養手当→ひとり親家庭\n特別児童扶養手当→障害児(の親)", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kofuku_01_003", "block_shuffle": 1, "question": "児童扶養手当の支給金額などについて定めている法律と言えば？", "question_img": null, "choices": ["児童手当法", "児童扶養手当法"], "answer": 1, "comment_1": "児童手当法とは別の法律です。\n\n同じ法律でも良いような気がするかもしれませんが、\n実は、児童扶養手当法は、児童手当法よりも前にできた法律なのです。\nこのように、流れを考えると、少し納得しやすいかもしれません。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kofuku_01_004", "block_shuffle": 1, "question": "主に障害児を養育する保護者を対象とした「特別児童扶養手当」の支給について定めている法律の名前は？", "question_img": null, "choices": ["児童手当法", "児童扶養手当法", "特別児童扶養手当等の支給に関する法律"], "answer": 2, "comment_1": "まとめると、こんな感じです。\n特別児童扶養手当だけ根拠法の名前が長いですね。\n\n児童手当\n→児童手当法\n\n児童扶養手当\n→児童扶養手当法\n\n特別児童扶養手当\n→特別児童扶養手当等の\n支給に関する法律", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kofuku_01_005", "block_shuffle": 1, "question": "特に「重度の障害」を持つ児童に対して支給される「障害児福祉手当」の根拠法は？", "question_img": null, "choices": ["児童手当法", "児童扶養手当法", "特別児童扶養手当等の支給に関する法律"], "answer": 2, "comment_1": "特別児童扶養手当等の支給に関する法律では、\n\n「特別児童扶養手当」\nだけでなく、\n\n「障害児福祉手当」\nも用意しています。\n\n法律の名前がややこしくなっている理由も、「2つあるから」と考えると納得しやすいですね。\nちなみに、この2つは併給も可能です。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kofuku_01_006", "block_shuffle": 1, "question": "この中で「所得制限」がないのはどれ？", "question_img": null, "choices": ["児童手当", "児童扶養手当", "特別児童扶養手当", "障害児福祉手当"], "answer": 0, "comment_1": "児童手当も以前は所得制限がありましたが、2024年の10月から撤廃されました。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kofuku_01_007", "block_shuffle": 1, "question": "「児童手当法」において「児童」とは?", "question_img": null, "choices": ["15歳に達する日以後の最初の3月31日までの間にある者", "18歳に達する日以後の最初の3月31日までの間にある者"], "answer": 1, "comment_1": "児童手当は、これまでは中学生まででしたが、高校生の年代まで支給されるようになりました。\n\n児童手当法改正(2024年10月)\n・中学生まで→高校生年代まで支給\n・所得制限の撤廃", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kofuku_01_008", "block_shuffle": null, "question": "「児童扶養手当法」において、「児童」とは、18歳に達する日以後の最初の3月31日までの間にある者を指すが、例外的に20歳未満までが対象になるのは？", "question_img": null, "choices": ["学生", "障害児"], "answer": 1, "comment_1": "児童扶養手当は年齢が2種類出てきます。\n\n【児童扶養手当】\n\n基本→18歳(3月31日)まで\n障害児→20歳未満", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kofuku_01_009", "block_shuffle": 1, "question": "「特別児童扶養手当等の支給に関する法律」において、障害児とは、障害等級に該当する程度の障害の状態にある、○○歳未満の者をいう。", "question_img": null, "choices": ["18歳未満", "20歳未満", "22歳未満"], "answer": 1, "comment_1": "ここで出てきた手当系については、\n基本→18歳(3月31日)まで\n障害児→20歳まで\n\nという法則が使えます。\n\n障害児が大人になると、障害年金をもらえる場合がありますが、障害年金は20歳からとなっていますので、切れ目ない支援のために、このように設計されているのかもしれませんね。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kofuku_01_010", "block_shuffle": 1, "question": "重度の障害児を対象とした「障害児福祉手当」が支給されるのは何歳未満？", "question_img": null, "choices": ["18歳未満", "20歳未満", "22歳未満"], "answer": 1, "comment_1": "この問題も、\n手当系の年齢制限\n\n基本→18歳(3月31日)まで\n障害児系→20歳未満\n\nの法則が使えます。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kofuku_01_011", "block_shuffle": null, "question": "児童扶養手当を受給している割合が高いのはどっち？", "question_img": null, "choices": ["母子世帯", "父子世帯"], "answer": 0, "comment_1": "児童扶養手当は所得制限がありましたね。\n\n統計的には母子世帯のほうが年収が低い世帯が多いため、受給率が高くなっています。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": "正誤", "pre_question": "○か×か。", "question_id": "kofuku_01_012", "block_shuffle": null, "question": "児童が海外在住の場合、短期留学などの例外を除き、原則として児童手当は支給されない。", "question_img": null, "choices": ["○", "×"], "answer": 0, "comment_1": "児童が日本国内に住所を有しない場合、例外はありますが、原則として手当は支給されません。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kofuku_01_013", "block_shuffle": null, "question": "子どもが児童養護施設に入所している場合、児童手当は誰に支給される？", "question_img": null, "choices": ["入所中の施設", "保護者", "児童相談所長", "どこにも支給されない"], "answer": 0, "comment_1": "乳児院やファミリーホーム、里親などの場合も同様に、施設や里親側が受け取ります。\n\nちなみに、里親手当を受け取っている場合でも、児童手当との併給が可能です。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kofuku_01_014", "block_shuffle": null, "question": "児童手当と児童扶養手当は、何か月に1回支給される？", "question_img": null, "choices": ["1か月に1回", "2か月に1回", "4か月に1回", "6か月に1回"], "answer": 1, "comment_1": "児童手当→偶数月\n児童扶養手当→奇数月\n\nとなっています。\nちなみに、児童手当と児童扶養手当は併給可能なので、同時に受給できます。", "goro_img": null, "comment_2": null, "mitei": null}]}
    ]},
    {"name":"社会福祉","enname":"shafuku","color":"rgba(154,205,50,1)","theme_list":[]},
    {"name":"教育原理","enname":"kyogen","color":"rgba(148,0,211,1)","theme_list":[
        {"theme": "○○カリキュラム", "quantity": 13, "theme_comment": "カリキュラムとは、「教育課程」のことです。\n教育原理では、「カリキュラム」と名の付くキーワードが頻出です。\n\nここでは「カリキュラム」系のキーワードを一気に学習し、しっかり見分けがつくように力をつけていきましょう。", "questions": [{"tag": 0, "q_type": null, "pre_question": "", "question_id": "kyogen_01_001", "block_shuffle": null, "question": "日常生活の中で自然と身についた規範や教育課程のことを何というか。", "question_img": null, "choices": ["潜在的カリキュラム", "経験カリキュラム", "アプローチカリキュラム", "コア・カリキュラム"], "answer": 0, "comment_1": "潜在的カリキュラムは、隠れたカリキュラムとも呼ばれます。\n\n【潜在的カリキュラムの例】\n子どもが無意識のうちに先生をお手本にする\n→先生が意識的に教えたものではなくても、子どもにとっては立派な学びです。\n\n保育の場面でも、自分の日頃の行いや言動をお手本にされる可能性があることを意識したいですね。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": "正誤", "pre_question": "○か×か。", "question_id": "kyogen_01_002", "block_shuffle": null, "question": "授業中に泣いている男児に対して、「男なのだから泣くのはやめなさい」と言って注意することは、ジェンダーバイアスを助長する「潜在的カリキュラム」になる可能性がある。", "question_img": null, "choices": ["○", "×"], "answer": 0, "comment_1": "これは潜在的カリキュラムの悪い例ですね。\nもちろん、先生の行動次第では、潜在的カリキュラムがいい方向へつながることもあります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kyogen_01_003", "block_shuffle": null, "question": "学ぶ内容をそれぞれの分野に分けて、系統的に教えるような編成をしたカリキュラム。", "question_img": null, "choices": ["教科カリキュラム", "経験カリキュラム", "スタートカリキュラム", "コア・カリキュラム"], "answer": 0, "comment_1": "小学校などで教科書に沿って教えているのが、まさに教科カリキュラムです。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kyogen_01_004", "block_shuffle": null, "question": "教科カリキュラムのデメリットと言えば？", "question_img": null, "choices": ["学習意欲が低下しやすい", "学習内容が偏りやすい", "教師側が習得状況を把握しにくい"], "answer": 0, "comment_1": "教科カリキュラムでは、体系的に教科書などに沿って順番に進めます。\n\nそのため、\n○網羅的に効率よく学べる\n○教師側が進み具合を把握しやすい\nなどのメリットがありますが、\n\n教科書の順番通りだと、子どもの興味関心とのずれが生じやすいので、\n×意欲が低下しやすい\nというデメリットがあります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kyogen_01_005", "block_shuffle": null, "question": "学習者の活動や体験を中心としながら学びを進めていくように、生活や経験を重視したカリキュラムを何というか。", "question_img": null, "choices": ["教科カリキュラム", "経験カリキュラム", "スタートカリキュラム", "コア・カリキュラム"], "answer": 1, "comment_1": "経験カリキュラムでは、子どもにとってはやりたいことができて楽しいですが、学びが偏りやすいというデメリットもあります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kyogen_01_006", "block_shuffle": null, "question": "幼児期の教育と言えば、どっち？", "question_img": null, "choices": ["教科カリキュラム", "経験カリキュラム"], "answer": 1, "comment_1": "小学校では体系的に学ぶ教科カリキュラムが中心で、幼稚園などでは子どもの興味を重視した経験カリキュラムが学びの中心になります。\n\n【まとめ】\n小学校→教科カリキュラム\n(体系的に学ぶ)\n\n幼稚園→経験カリキュラム\n(子どもの興味を重視)", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kyogen_01_007", "block_shuffle": null, "question": "体験学習や問題解決学習が多く取り入れられるのはどっち？", "question_img": null, "choices": ["教科カリキュラム", "経験カリキュラム"], "answer": 1, "comment_1": null, "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kyogen_01_008", "block_shuffle": null, "question": "小学校への入学を控えた年長児に対して行う、小学校での生活や学習を意識したカリキュラムのことをなんと言うか。", "question_img": null, "choices": ["融合カリキュラム", "カリキュラム・マネジメント", "アプローチカリキュラム", "コア・カリキュラム"], "answer": 2, "comment_1": "年長さんが小学校にアプローチする、つまり近づくのでアプローチカリキュラムです。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kyogen_01_009", "block_shuffle": null, "question": "小学校に入学したばかりの1年生が受けるカリキュラムのことをなんと言うか。", "question_img": null, "choices": ["スタートカリキュラム", "カリキュラム・マネジメント", "融合カリキュラム", "コア・カリキュラム"], "answer": 0, "comment_1": "小学校の生活がすでにスタートしているのでスタートカリキュラムですね。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kyogen_01_010", "block_shuffle": null, "question": "小学校に入学した後、小学校生活になかなか馴染めず、問題行動が続く状態をなんと呼ぶ？", "question_img": null, "choices": ["小1プロブレム", "小1の壁"], "answer": 0, "comment_1": "小1問題、小1ギャップとも呼ばれます。\n\nちなみに「小1の壁」はどちらかというと親寄りの問題で、\n特に保育所と比べて\n・下校が早い\n・夏休みが長い\n・会社などで支援が受けにくい\n\nなどの理由から、仕事と子育ての両立が難しくなることを指します。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kyogen_01_011", "block_shuffle": null, "question": "教育課程(カリキュラム)を実施・評価して改善していくことを何というか。", "question_img": null, "choices": ["カリキュラム・マネジメント", "融合カリキュラム", "コア・カリキュラム", "アプローチカリキュラム"], "answer": 0, "comment_1": "カリキュラムマネジメントでは、カリキュラムを実施して評価して改善します。\nカリキュラムマネジメントによって教育の「質の向上」を目指します。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kyogen_01_012", "block_shuffle": null, "question": "学習の中核となる科目などを設け、そこを中心に周辺分野を組織する教育課程のことを何と言う？", "question_img": null, "choices": ["経験カリキュラム", "カリキュラム・マネジメント", "融合カリキュラム", "コア・カリキュラム"], "answer": 3, "comment_1": "中核、つまりコアがあるのでコアカリキュラムです。\n\n教員の養成や医師・看護師の養成などの場面でよく出てきます。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "kyogen_01_013", "block_shuffle": null, "question": "関連する複数の教科・科目を統合して、一つの新しい学習領域として再構成したものを何と言う？", "question_img": null, "choices": ["経験カリキュラム", "カリキュラム・マネジメント", "融合カリキュラム", "コア・カリキュラム"], "answer": 2, "comment_1": "融合カリキュラムの例として有名なのは、社会科です。\n\n・地理\n・歴史\n・公民\nという3つのジャンルを社会科としてまとめています。", "goro_img": null, "comment_2": null, "mitei": null}]}
    ]},
    {"name":"社会的養護","enname":"shayou","color":"rgba(34,139,34,1)","theme_list":[
    {"theme": "養子縁組", "quantity": 12, "theme_comment": "養子縁組は、養親と養子との間に法律上の親子関係を作り出す制度で、\n\n・普通養子縁組\n・特別養子縁組\n\nの2種類があります。\n\nこのうち特に社会的養護と関係が深いのは特別養子縁組です。\nここでは主に「特別養子縁組」について学びましょう。", "questions": [{"tag": 0, "q_type": null, "pre_question": "", "question_id": "shayou_01_001", "block_shuffle": 1, "question": "特別養子縁組が行われた後、元の親との戸籍上の親子関係はどうなる？", "question_img": null, "choices": ["継続する", "終了する"], "answer": 1, "comment_1": "特別養子縁組では、元の親子関係は終了します。\n\n【元の親子関係】\n普通養子縁組→継続\n特別養子縁組→終了", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "shayou_01_002", "block_shuffle": null, "question": "特別養子縁組が行われた後、新しい養親との戸籍上の親子関係はどうなる？", "question_img": null, "choices": ["養子または養女と記載される", "実子と同じ扱いになる"], "answer": 1, "comment_1": "特別養子縁組の後は、法的に実子と同じように扱われます。\n\n普通養子縁組では戸籍は\n・続柄は養子、養女\n・元の親も併記\nという形になりますが、\n\n特別養子縁組では、\n・続柄は長男、長女など\n・元の親との関係は終了\nとなります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": "正誤", "pre_question": "○か×か。", "question_id": "shayou_01_003", "block_shuffle": null, "question": "子どもに永続的な家族関係をベースにしたパーマネンシーを保障するために、特別養子縁組や普通養子縁組は実父母の死亡などの場合に限られる。", "question_img": null, "choices": ["○", "×"], "answer": 1, "comment_1": "例えばひどい虐待など、家庭復帰が見込めない場合などでも検討されます。\n特別養子縁組は、その子どもの利益のため特に必要があると認めるときに成立させるものであり、実の両親が死亡した場合に限ったものではありません。\n\nちなみに普通養子縁組は相続対策などで使われたりもする制度なので、活用するのは子どもとも限りません。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "shayou_01_004", "block_shuffle": null, "question": "特別養子縁組の成立のためには、どこに申し立てを行う？", "question_img": null, "choices": ["市町村長", "都道府県知事", "家庭裁判所", "児童相談所"], "answer": 2, "comment_1": "「裁判所」というとなかなかハードルが高い感じもしますが、\n\n・元の親子関係が終了\n・新しく法的な親子関係を結ぶ\n\nという感じで、\n「子どもの人生に大きく関わることだから」\nと考えると納得しやすいですね。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "shayou_01_005", "block_shuffle": null, "question": "特別養子縁組で、養子となる者の上限年齢は、特別養子縁組の成立の審判の申立て時に、原則として何歳未満？", "question_img": null, "choices": ["6歳未満", "12歳未満", "15歳未満", "20歳未満"], "answer": 2, "comment_1": "「民法」に書かれている内容です。\n\n以前は6歳未満でしたが、改正されて原則15歳未満になりました。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "shayou_01_006", "block_shuffle": null, "question": "特別養子縁組で、養子となる者の上限年齢は原則として15歳未満だが、例外的に「18歳未満」に引き上げることができる条件と言えば？", "question_img": null, "choices": ["子どもに障害がある場合", "子どもが就学中の場合", "子どもが養親となる者に15歳未満の時から養育されている場合", "実親が縁組に反対していた場合"], "answer": 2, "comment_1": "やむを得ず請求が15歳までに間に合わなかった場合、という条件付きですが、\n\n子どもが養親となる者に15歳未満の時から養育されている場合は、\n例外的に18歳未満になります。\n\n【民法(特別養子縁組について)】\n養子となる者が十五歳に達する前から引き続き養親となる者に監護されている場合において、十五歳に達するまでに請求がされなかったことについてやむを得ない事由があるときは、適用しない。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "shayou_01_007", "block_shuffle": null, "question": "特別養子縁組で、「子どもの」同意が必要になるのは何歳から？", "question_img": null, "choices": ["6歳以上", "10歳以上", "12歳以上", "15歳以上"], "answer": 3, "comment_1": "【民法】\n養子となる者が十五歳に達している場合においては、特別養子縁組の成立には、その者の同意がなければならない。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": "正誤", "pre_question": "○か×か。", "question_id": "shayou_01_008", "block_shuffle": null, "question": "特別養子縁組では、「実の親」の同意を必要としない。", "question_img": null, "choices": ["○", "×"], "answer": 1, "comment_1": "原則として「実の親」の同意は必要です。\n\nただし、意思表示ができない場合や、虐待などがある場合は、同意は不要となります。\n\n【民法】\n特別養子縁組の成立には、養子となる者の父母の同意がなければならない。\nただし、父母がその意思を表示することができない場合又は父母による虐待、悪意の遺棄その他養子となる者の利益を著しく害する事由がある場合は、この限りでない。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "穴埋め問題。", "question_id": "shayou_01_009", "block_shuffle": null, "question": "特別養子縁組の成立には、養親となる者が養子となる者を○○以上監護した状況を考慮しなければならない。", "question_img": null, "choices": ["3か月", "6か月", "1年", "3年"], "answer": 1, "comment_1": "特別養子縁組が成立してから「はじめまして」では困りますよね。\n\n里親制度などを使って6か月以上一緒に暮らしてみて、それからでないと特別養子縁組はできないということです。\n\nちなみに、特別養子縁組を希望する場合「養子縁組里親」という制度が使えます。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": "正誤", "pre_question": "○か×か。", "question_id": "shayou_01_010", "block_shuffle": null, "question": "特別養子縁組では、原則として夫婦が共同で縁組を行う。", "question_img": null, "choices": ["○", "×"], "answer": 0, "comment_1": "特別養子縁組は、夫婦で行います。\n(つまり独身だとダメで、夫婦の片方だけ縁組、みたいなことも基本できません)\n\n【民法】\n養親となる者は、配偶者のある者でなければならない。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "shayou_01_011", "block_shuffle": null, "question": "特別養子縁組で養親となるものの年齢は原則として何歳以上？", "question_img": null, "choices": ["18歳以上", "20歳以上", "25歳以上", "30歳以上"], "answer": 2, "comment_1": "原則25歳以上です。\nただし、片方が25歳以上なら、もう片方は20歳以上でもOKとなっています。\n\n【民法】\n二十五歳に達しない者は、養親となることができない。ただし、養親となる夫婦の一方が二十五歳に達していない場合においても、その者が二十歳に達しているときは、この限りでない。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "shayou_01_012", "block_shuffle": null, "question": "養子縁組を前提とする里親の年齢として望ましいとされるのは？", "question_img": null, "choices": ["子どもが20歳に達した時に、概ね65歳以下", "里親を開始する段階で45歳以下"], "answer": 0, "comment_1": "「望ましい」というものなので、これは絶対守るべきルール、というわけではありません。\n\n25歳以上(片方は20歳以上でも可)\n→民法上の規定\n\n子が20歳時点で65歳未満\n→ルールではなく目安\n\n子どもが大きくなった時に養親が高齢になりすぎないように、という配慮ですね。", "goro_img": null, "comment_2": null, "mitei": null}]}
    ]},
    {"name":"子どもの保健","enname":"hoken","color":"rgba(0,191,255,1)","theme_list":[
        {"theme": "乳幼児の生理的特徴", "quantity": 10, "theme_comment": null, "questions": [{"tag": 0, "q_type": null, "pre_question": "", "question_id": "hoken_01_001", "block_shuffle": null, "question": "1分間の呼吸数が多いのはどっち？", "question_img": null, "choices": ["乳幼児", "成人"], "answer": 0, "comment_1": "年齢が低いほど呼吸数は多くなります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": "正誤", "pre_question": "○か×か。", "question_id": "hoken_01_002", "block_shuffle": null, "question": "乳幼児の呼吸は、成人に比べて腹式呼吸の要素が強い。", "question_img": null, "choices": ["○", "×"], "answer": 0, "comment_1": null, "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hoken_01_003", "block_shuffle": null, "question": "基礎代謝が高く、体重1kgに対して必要なエネルギー量が多いのはどっち？", "question_img": null, "choices": ["乳幼児", "成人"], "answer": 0, "comment_1": "成長する分、エネルギーが沢山必要だと考えると分かりやすいですね。\n年齢が低いほど基礎代謝は高くなります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hoken_01_004", "block_shuffle": null, "question": "血圧が高いのはどっち？", "question_img": null, "choices": ["乳幼児", "成人"], "answer": 1, "comment_1": "血圧は、年齢とともに上がる傾向にあります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hoken_01_005", "block_shuffle": 1, "question": "体内で解剖学的な変化が起こり、血液循環が「成人型循環」に変化するタイミングは？", "question_img": null, "choices": ["誕生した時", "3歳ごろ", "6歳ごろ", "12歳ごろ"], "answer": 0, "comment_1": "生まれた時に、肺呼吸の開始と同時に、\n胎児循環から成人型循環に変わります。\n\n【胎児の時】\n→胎盤から酸素を受け取る\n\n【生まれてから】\n→肺から酸素を受け取る", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hoken_01_006", "block_shuffle": null, "question": "1分間の脈拍が多いのはどっち？", "question_img": null, "choices": ["乳幼児", "成人"], "answer": 0, "comment_1": null, "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hoken_01_007", "block_shuffle": null, "question": "体温が高い傾向にあるのはどっち？", "question_img": null, "choices": ["乳幼児", "成人"], "answer": 0, "comment_1": "体温調節機能も未熟なので、体温は変動しやすく、\n環境や活動、泣いた後などの影響を受けやすいです。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hoken_01_008", "block_shuffle": null, "question": "体重当たりの水分量が多いのはどっち？", "question_img": null, "choices": ["乳幼児", "成人"], "answer": 0, "comment_1": "新生児の水分量は80%にもなります。\n成人だと50-60%ぐらいです。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "hoken_01_009", "block_shuffle": null, "question": "体重当たりの体表面積が広く、不感蒸泄の量が多くなりやすいのはどっち？", "question_img": null, "choices": ["乳幼児", "成人"], "answer": 0, "comment_1": "不感蒸泄とは、皮膚の表面から「蒸発する」形で出ていく水分のことです。\n汗とは区別されます。\n\n不感蒸泄が多いと、水分が体から出ていくスピードも速くなるので、脱水に気を付ける必要があります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": "正誤", "pre_question": "○か×か。", "question_id": "hoken_01_010", "block_shuffle": null, "question": "乳幼児は腎機能が未熟なため、水分や電解質のバランスが崩れやすい。", "question_img": null, "choices": ["○", "×"], "answer": 0, "comment_1": "特に小さな子どもの食事は塩分控えめにしますが、腎機能が未熟だから、というのも理由の一つです。\n(味覚の問題だけではないのです)", "goro_img": null, "comment_2": null, "mitei": null}]}
    ]},
    {"name":"子どもの食と栄養","enname":"eiyou","color":"rgba(255,165,0,1)","theme_list":[
        {"theme": "こ食", "quantity": 7, "theme_comment": null, "questions": [{"tag": 0, "q_type": null, "pre_question": "", "question_id": "eiyou_01_001", "block_shuffle": null, "question": "「個食」の意味は？", "question_img": null, "choices": ["ひとりで食事をすること", "家族がばらばらのものを食べること", "粉ものばかり食べること", "食べる量が少ないこと"], "answer": 1, "comment_1": "「個食」は、家族が同じ食卓にいるのに、それぞれがバラバラなものを食べていることです。\n\n「個別」の「個」ですね。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "eiyou_01_002", "block_shuffle": null, "question": "ひとりで食事をすることを何と言う？", "question_img": null, "choices": ["孤食", "個食", "小食", "粉食"], "answer": 0, "comment_1": "「孤独」の「孤」ですね。\n\n孤食ばかりだと、\n・偏食になりやすい\n・社会性が育ちにくい\n・食事作法などを学べない\n\nなどの問題が出てきやすくなります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "eiyou_01_003", "block_shuffle": null, "question": "「固食」の意味は？", "question_img": null, "choices": ["固いものばかり食べること", "同じものばかりを食べること"], "answer": 1, "comment_1": "「固定」の固だと考えると分かりやすいと思います。\n\n同じものや好きなものばかりを食べるため、\n栄養が偏りやすくなります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": "正誤", "pre_question": "○か×か。", "question_id": "eiyou_01_004", "block_shuffle": null, "question": "粉に挽いてあるものを好んで主食にする「粉食」では、噛む回数が少なくなりやすい。", "question_img": null, "choices": ["○", "×"], "answer": 0, "comment_1": "「粉食」は、例えばうどん、お好み焼き、パン、バスタなどです。\n柔らかいものが多いため、噛む回数が少なくなりがちです。\n\n【噛むことのメリット】\n・満腹中枢に働きかけて食べ過ぎを防ぐ\n・脳の血流アップ\n・唾液の分泌を促す", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "eiyou_01_005", "block_shuffle": null, "question": "大人が不在で、子ども(たち)だけで食事をすることを何と言う？", "question_img": null, "choices": ["子食", "孤食", "小食", "個食"], "answer": 0, "comment_1": "名前の通りですね。\n\n大人の目が届かないので、\n・偏食になりやすい\n・食事作法などを学べない\n\nなどの問題が出てきやすくなります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": "正誤", "pre_question": "○か×か。", "question_id": "eiyou_01_006", "block_shuffle": null, "question": "食べる量が少ないことを意味する「小食」では、発育に必要な栄養が不足しやすい。", "question_img": null, "choices": ["○", "×"], "answer": 0, "comment_1": "もちろん食べる量には個人差がありますが、\n\n例えば\n・お菓子の食べ過ぎ\n・無理なダイエット\n・運動不足\n・心身の不調\n\nなどが隠れていることもあります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "eiyou_01_007", "block_shuffle": null, "question": "濃い味付けを好む「濃食」で特に問題になりやすいのは？", "question_img": null, "choices": ["摂取カロリーが足りなくなる", "肥満や生活習慣病になりやすい", "食事のマナーが身に付きにくい"], "answer": 1, "comment_1": "「濃食」の特徴は、\n\n「塩分や糖分が多い」\nことです。\n\nまた、濃食で多い加工食品では、脂肪分なども多い傾向にありますので、\n肥満や生活習慣病につながりやすくなります。", "goro_img": null, "comment_2": null, "mitei": null}]},
        {"theme": "6つの基礎食品群", "quantity": 10, "theme_comment": "今回のテーマは「6つの基礎食品群」。\n\n「6つも覚えるなんて大変そう」\nと思われがちですが、\n語呂合わせがあれば一発です。\n\n無理なく覚えていきましょう。", "questions": [{"tag": 0, "q_type": null, "pre_question": "", "question_id": "eiyou_02_001", "block_shuffle": null, "question": "6つの基礎食品群のうち、第1群と第2群は、3色食品群のどの色と対応している？", "question_img": null, "choices": ["赤", "黄", "緑"], "answer": 0, "comment_1": "【3色食品群との対応】\n\n1,2群→赤(体を作る)\n3,4群→緑(調子を整える)\n5,6群→黄色(エネルギー)", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "eiyou_02_002", "block_shuffle": null, "question": "6つの基礎食品群のうち、第3群と第4群は、3色食品群のどの色と対応している？", "question_img": null, "choices": ["赤", "黄", "緑"], "answer": 2, "comment_1": "【3色食品群との対応】\n\n1,2群→赤(体を作る)\n3,4群→緑(調子を整える)\n5,6群→黄色(エネルギー)", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "eiyou_02_003", "block_shuffle": null, "question": "6つの基礎食品群のうち、第5群と第6群は、3色食品群のどの色と対応している？", "question_img": null, "choices": ["赤", "黄", "緑"], "answer": 1, "comment_1": "【3色食品群との対応】\n\n1,2群→赤(体を作る)\n3,4群→緑(調子を整える)\n5,6群→黄色(エネルギー)", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "eiyou_02_004", "block_shuffle": null, "question": "魚、肉、卵、大豆製品など、「たんぱく質」を多く含む食品は、第何群？", "question_img": null, "choices": ["第1群", "第2群", "第3群", "第4群"], "answer": 0, "comment_1": "6つの基礎食品群の覚え方は、「たかるカビ都市」です。\n栄養満点すぎてカビが生えまくっている大都市を想像しましょう。", "goro_img": "たかるカビ都市", "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "eiyou_02_005", "block_shuffle": null, "question": "牛乳、乳製品、海藻、小魚など、「カルシウム」を多く含む食品は第何群？", "question_img": null, "choices": ["第1群", "第2群", "第3群", "第4群"], "answer": 1, "comment_1": "1群と2群は、\n体を作る「赤の食べ物」\nでもありますね。\n\n", "goro_img": "たかるカビ都市", "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "eiyou_02_006", "block_shuffle": null, "question": "「カロテン」を含む緑黄色野菜と言えば、第何群？", "question_img": null, "choices": ["第3群", "第4群", "第5群", "第6群"], "answer": 0, "comment_1": "カロテンは、体内で(必要な分だけ)ビタミンAに変換されます。", "goro_img": "たかるカビ都市", "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "eiyou_02_007", "block_shuffle": null, "question": "「ビタミンC」などを含む「その他の野菜(淡色野菜)」として分類されるのは第何群？", "question_img": null, "choices": ["第3群", "第4群", "第5群", "第6群"], "answer": 1, "comment_1": "まずは第3群の緑黄色野菜を覚えて、それ以外の野菜や果物は基本的に第4群、と考えると覚えやすいです。", "goro_img": "たかるカビ都市", "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "eiyou_02_008", "block_shuffle": null, "question": "第3群に分類される「緑黄色野菜」に含まれるのはどれ？", "question_img": null, "choices": ["にんじん、トマト、かぼちゃ、ブロッコリー", "きゅうり、キャベツ、もやし、ナス", "りんご、みかん、ブドウ", "じゃがいも、さつまいも、とうもろこし"], "answer": 0, "comment_1": "緑黄色野菜をざっくり見分ける方法は、\n「切った時に中身まで色が濃い野菜」\nです。\n\n【緑黄色野菜（3群）】\nにんじん、トマト、かぼちゃ、\nブロッコリー、ほうれん草、ピーマン\n\n【その他の野菜（4群）】\nきゅうり、キャベツ、もやし、ナス、\nりんご、みかん、ブドウ\n\nちなみに、糖質が多いものは5群になるのでこれも注意です。\n【炭水化物（5群）】\nじゃがいも、さつまいも、とうもろこし、米", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "eiyou_02_009", "block_shuffle": null, "question": "「糖質」を多く含む食品と言えば、第何群？", "question_img": null, "choices": ["第3群", "第4群", "第5群", "第6群"], "answer": 2, "comment_1": "米などの穀類、いも類、そして砂糖なども第5群に含まれます。", "goro_img": "たかるカビ都市", "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "eiyou_02_010", "block_shuffle": null, "question": "「脂質」を多く含む食品と言えば、第何群？", "question_img": null, "choices": ["第3群", "第4群", "第5群", "第6群"], "answer": 3, "comment_1": "脂質と言えば油ですが、\n\nサラダ油やバターだけでなく、\n「脂肪分の多い」肉や、ナッツ類も含まれます。", "goro_img": "たかるカビ都市", "comment_2": null, "mitei": null}]}
    ]},
    {"name":"保育実習理論","enname":"jisshu","color":"rgba(255,215,0,1)","theme_list":[
        {"theme": "描画技法", "quantity": 14, "theme_comment": "マーブリング、コラージュなどの描画表現の技法について学びます。\n美術の授業などで習ったという方も多いかもしれません。\n\nカタカナのキーワードが多くて大変ですが、保育の現場でも実際に活用するケースは多いですので、イメージしながら覚えていきましょう。", "questions": [{"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_01_001", "block_shuffle": null, "question": "指に直接絵の具をつけて絵を描く技法のことをなんと言うか。", "question_img": null, "choices": ["デカルコマニー", "フィンガーペインティング", "フロッタージュ", "スタンピング"], "answer": 1, "comment_1": "指でペイントするからフィンガーペインティング、そのままですね。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_01_002", "block_shuffle": null, "question": "凸凹があるものの表面に薄い紙をのせて鉛筆やクレヨンで上からこすり、材質の地肌を写しとる方法をなんと言う？", "question_img": null, "choices": ["デカルコマニー", "スクラッチ", "フロッタージュ", "スタンピング"], "answer": 2, "comment_1": "10円玉などで試してみると、綺麗に写し取れて面白いです。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_01_003", "block_shuffle": null, "question": "フロッタージュの時に使う紙はどっちが良い？", "question_img": null, "choices": ["薄い紙", "厚い紙"], "answer": 0, "comment_1": "模様を写し取りやすいのは、薄くて柔らかい紙ですね。なんとなくイメージしましょう。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_01_004", "block_shuffle": null, "question": "びんのふたや消しゴムなどに絵の具をつけて、紙などに押して写す方法をなんと言う？", "question_img": null, "choices": ["デカルコマニー", "スクラッチ", "バチック", "スタンピング"], "answer": 3, "comment_1": "やっていることはスタンプなので、スタンピングです。\n(分かりやすいですね。)", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_01_005", "block_shuffle": null, "question": "紙を二つ折りにして片方に絵の具をつけ、もう片方と重ね合わせて手でこすると左右対称の模様ができる。この技法のことをカタカナでなんと言う？", "question_img": null, "choices": ["デカルコマニー", "スクラッチ", "バチック", "マーブリング"], "answer": 0, "comment_1": "左右対称、ときたらデカルコマニーです。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_01_006", "block_shuffle": null, "question": "下地にクレヨンなどの明るい色を塗って、その上にクレヨンの黒など暗い色を重ねて塗り、画面を先のとがったものでひっかいて形を描き、下地の色を出す方法をなんと言う？", "question_img": null, "choices": ["スパッタリング", "スクラッチ", "バチック", "マーブリング"], "answer": 1, "comment_1": "ひっかいたら絵が描けるのでスクラッチ、そのままですね。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_01_007", "block_shuffle": null, "question": "「はじき絵」とも呼ばれ、クレヨンで絵を描いた部分に絵の具を塗ると、絵の具がはじかれることを応用した表現技法をカタカナでなんと言うか。", "question_img": null, "choices": ["スパッタリング", "コラージュ", "バチック", "マーブリング"], "answer": 2, "comment_1": "「バチっ」とはじくのでバチックです。\n\nクレヨンが、絵の具をはじきます。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_01_008", "block_shuffle": null, "question": "「はじき絵(バチック)」を描くとき、きれいに絵の具をはじくための、クレヨンの塗り方のコツは？", "question_img": null, "choices": ["弱く、薄く塗る", "強く、濃く塗る"], "answer": 1, "comment_1": null, "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_01_009", "block_shuffle": null, "question": "「はじき絵(バチック)」を描くとき、きれいに絵の具をはじくためには、絵の具の水分量をどうする？", "question_img": null, "choices": ["水分を多めにする", "水分を少なめにする"], "answer": 0, "comment_1": "【バチックのコツ】\n\n・クレヨンは強く、濃く\n・絵の具は水分多め", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_01_010", "block_shuffle": null, "question": "絵の具などを直接ぽたぽたと垂らして表現する技法の名前は？", "question_img": null, "choices": ["スパッタリング", "スクラッチ", "ドリッピング", "フィンガーペインティング"], "answer": 2, "comment_1": "「ドリップ」には、ぽたぽたと滴るという意味があります。\nドリップコーヒーや肉汁のドリップなどですね。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_01_011", "block_shuffle": null, "question": "平らな容器に水を張り、墨汁または油性絵の具を油で薄めたものや、専用の絵の具などを水の表面に浮かして、水の上にできた模様を紙に写し取る方法と言えば？", "question_img": null, "choices": ["スパッタリング", "コラージュ", "ドリッピング", "マーブリング"], "answer": 3, "comment_1": "マーブリングを使うと、マーブル模様が出来上がります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_01_012", "block_shuffle": null, "question": "マーブリングの別名は？", "question_img": null, "choices": ["墨流し", "吹き流し"], "answer": 0, "comment_1": "ちなみに、吹き流しは、紙の上に垂らした絵の具をストローなどで吹く技法です。\n偶然できる模様を楽しむことができます。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_01_013", "block_shuffle": null, "question": "紙や布、写真などを貼り合わせて作る表現技法をカタカナでなんと言う？", "question_img": null, "choices": ["スパッタリング", "コラージュ", "ドリッピング", "デカルコマニー"], "answer": 1, "comment_1": "大人でも、写真を貼り合わせて日記を作ったりするなど、趣味として楽しむ方は多いですね。\nけっこう身近な技法だと思います。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_01_014", "block_shuffle": null, "question": "絵の具をつけたブラシや網などを使い、絵の具を細かくはね散らして表現する技法を何という？", "question_img": null, "choices": ["スパッタリング", "スクラッチ", "ドリッピング", "フィンガーペインティング"], "answer": 0, "comment_1": "ブラシや網などを使うことで、霧のような細かい点をつくることができます。\n\n型紙などを置いた上から絵の具を散らす方法もあります。", "goro_img": null, "comment_2": null, "mitei": null}]},
        {"theme": "わらべうた", "quantity": 6, "theme_comment": "「わらべうた」の問題は頻出ですが、気軽に取り組みやすい範囲です。\nサクッと勉強していきましょう。", "questions": [{"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_02_001", "block_shuffle": null, "question": "わらべうたの説明として正しいのはどっち？", "question_img": null, "choices": ["教育のために、主に明治～昭和初期に作られた曲の総称である。", "子ども達が遊びながら歌い、受け継がれてきた歌である。"], "answer": 1, "comment_1": "わらべうたは、作者不詳だったり、いつできたのか不明だったりすることもあります。\n\nちなみに、教育のために、主に明治～昭和初期に作られた曲は、「唱歌」と呼ばれます。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": "正誤", "pre_question": "○か×か。", "question_id": "jisshu_02_002", "block_shuffle": null, "question": "わらべうたは、時代や地域によって変化していくことがある。", "question_img": null, "choices": ["○", "×"], "answer": 0, "comment_1": "まるで方言のように、わらべうたにも地域による違いがあるものがあります。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_02_003", "block_shuffle": null, "question": "わらべうたの音楽的特徴はどっち？", "question_img": null, "choices": ["音域が広い", "音域が狭い"], "answer": 1, "comment_1": "わらべうたは、子どもにとって歌いやすいものが多いです。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_02_004", "block_shuffle": null, "question": "わらべうたの音楽的特徴はどっち？", "question_img": null, "choices": ["音の高さの変化が大きい", "音の高さが急に変わることが少ない"], "answer": 1, "comment_1": "音の高さが急に変わる曲は大人にとってもけっこう難しいですよね。", "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_02_005", "block_shuffle": 1, "question": "日本の民謡やわらべうたで多いのはどっち？", "question_img": null, "choices": ["5音音階", "7音音階"], "answer": 0, "comment_1": null, "goro_img": null, "comment_2": null, "mitei": null}, {"tag": 0, "q_type": null, "pre_question": "", "question_id": "jisshu_02_006", "block_shuffle": 1, "question": "2つの音だけでできている「わらべうた」は、どっちの音で終わることが多い？", "question_img": null, "choices": ["上の音(高い音)", "下の音(低い音)"], "answer": 0, "comment_1": "なぜか試験に出る問題です。\n音が2つだけのわらべうたとしては、\n\nどちらにしようかな、天の神様の言うとおり\n\nなどが有名です。\nこれも高い方の音で終わっていますね。\n\n(ちなみにこの歌の続きは、結構地域差があるようです。色々な出身の方に聞いてみると面白いかもしれません。)", "goro_img": null, "comment_2": null, "mitei": null}]}
            ]}
];


